contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test driver
    function run(address depositor, uint amount) public {
        // preconditions: caller has enough balance to forward value
        require(address(this).balance >= amount);
        // ensure we target the boundary: amount equals MinDeposit
        uint min = c.MinDeposit();
        require(amount == min);

        // read balance before
        uint before = c.balances(depositor);

        // perform deposit from this contract to c on behalf of 'depositor'
        // since c.Deposit uses msg.sender, we must call it from this contract
        // but balances map is keyed by msg.sender, so to exercise depositor we
        // need to simulate calling from that address. Instead, we choose depositor == address(this)
        // enforce that depositor is this contract's address
        require(depositor == address(this));

        // call Deposit forwarding amount
        c.Deposit{value: amount}();

        // read balance after
        uint after = c.balances(depositor);

        // property: depositing exactly MinDeposit must not increase recorded balance
        assert(after == before);
    }

    // allow this test contract to receive ETH for making deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // depositAmount is the Ether to send to c.Deposit; depositor is msg.sender of this call
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // Precondition: ensure the contract currently has some prior balance baseline
        uint before = address(c).balance;
        // Call Deposit with provided Ether
        c.Deposit{value: depositAmount}();
        uint after = address(c).balance;
        // General rule: if depositAmount equals c.MinDeposit() then the contract balance should not increase
        // (original contract ignores exact-MinDeposit deposits); mutant accepts >= and thus increases balance.
        assert(!(depositAmount == c.MinDeposit() && after > before));
    }
    receive() external payable {}
}

