        // require we test the case strictly less than MinDeposit
        require(depositAmount < minDep);
        // ensure this contract has enough balance to send
        require(address(this).balance >= depositAmount);

        // ensure depositor's prior recorded balance is zero
        // balances is public mapping, accessible as balances(address)
        require(c.balances(address(this)) == 0);

        // perform the deposit (this is the state-changing call under test)
        c.Deposit{value: depositAmount}();

        // After calling Deposit with amount < MinDeposit, recorded balance must remain zero
        assert(c.balances(address(this)) == 0);
    }

    receive() external payable {}
}

