        // preconditions: this contract must have enough ether to send amt
        require(address(this).balance >= amt, "insufficient balance for test");
        // ensure amt is strictly less than c.MinDeposit()
        uint minD = c.MinDeposit();
        require(amt < minD, "amt must be smaller than MinDeposit to distinguish behavior");

        // read balance before
        uint before = c.balances(address(this));

        // perform the Deposit call on c with value amt
        c.Deposit{value: amt}();

        // read balance after
        uint after = c.balances(address(this));

        // In original P, deposits with value < MinDeposit are ignored, so after == before.
        // In mutated M (guard removed) such small deposits increase the stored balance, violating this assertion.
        assert(after == before);
    }

    // allow this contract to receive ether so tests can fund it
    receive() external payable {}
}

