pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters:
    // - depositor: an address that will call Deposit()
    // - depAmt: amount to send in Deposit()
    // - withdrawAmt: amount passed to CashOut()
    // We keep assumptions wide: amounts bounded to < 10 ether to keep test practical.
    function testFuzz_property(address depositor, uint256 depAmt, uint256 withdrawAmt) public {
        // Keep fuzz domain reasonable but wide
        depositor = address(uint160(uint256(keccak256(abi.encodePacked(depositor))))); // canonicalize address
        vm.deal(depositor, 10 ether);

        depAmt = bound(depAmt, 0, 10 ether);
        withdrawAmt = bound(withdrawAmt, 0, 10 ether);

        // Make depositor perform Deposit with depAmt
        vm.prank(depositor);
        c.Deposit{value: depAmt}();

        // Now call CashOut as depositor (the difference can affect balances at any key via deposits/withdrawals)
        // We capture whether call succeeds (but main property reads public balances)
        bool ok;
        try c.CashOut(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: for the reference contract, balances(depositor) is never less than zero and is consistent with deposits accepted only when > MinDeposit.
        // We express a universal property that the reference's balances equals the recorded public getter (this always holds): reading balances via public getter should be non-negative.
        // To make this assertion meaningful against the mutant: because the reference ignores deposits <= MinDeposit, any small deposit that the mutant would have accepted can only increase the mutant's balances compared to the reference. Thus, in the reference, balances(depositor) <= address(c).balance + type(uint256).max (trivial) — to craft a precise universal property we assert the reference's balances never increases due to deposits <= MinDeposit: i.e., if depAmt <= c.MinDeposit(), then balances(depositor) == 0 after deposit and before cashout.

        // Compute MinDeposit via public getter
        uint256 minD = c.MinDeposit();

        // If deposit was <= MinDeposit, reference ignores it, so depositor's balance must be 0 before any cashout; since we called CashOut after Deposit, the balance after CashOut must still be <= previous (i.e., 0) but balances are unsigned so equals 0.
        // This is a single assertTrue property reading c's public getter that holds for reference for all inputs and is violated by the mutant for some inputs (mutant accepts <=MinDeposit deposits).

        if (depAmt <= minD) {
            // In reference C, deposits with msg.value <= MinDeposit are ignored, so balances(depositor) must be 0 (both before and after CashOut).
            assertTrue(c.balances(depositor) == 0);
        } else {
            // For deposits > MinDeposit the reference accepts them; after possibly cashing out, balances(depositor) is some value >= 0.
            // We assert it's a valid uint (non-negative) by checking equality to itself — this satisfies the requirement of a single assertTrue reading c's public surface and ensures the test compiles and runs.
            assertTrue(c.balances(depositor) >= 0);
        }
    }
}

