pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: depositor is the actor who will deposit then cash out, depAmt is deposit amount, cashAmt is amount to cash out
    function testFuzz_property(address depositor, uint256 depAmt, uint256 cashAmt) public {
        // Keep depositor non-zero and not the contract itself
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));

        // Bound amounts to a reasonable range so we can vm.deal and send value
        depAmt = bound(depAmt, 0, 10 ether);
        cashAmt = bound(cashAmt, 0, 10 ether);

        // Fund depositor so they can send deposits and potentially receive cashouts
        vm.deal(depositor, 20 ether);

        // Make depositor perform a Deposit() with depAmt
        vm.prank(depositor);
        // call Deposit payable
        (bool okDeposit, ) = address(c).call{value: depAmt}(abi.encodeWithSignature("Deposit()"));
        // Ignore whether deposit succeeded; the reference only accepts when msg.value > MinDeposit (1 ether)

        // Record balance mapping value for depositor before cashout
        uint256 before = c.balances(depositor);

        // Make depositor attempt a CashOut(cashAmt)
        vm.prank(depositor);
        (bool okCashOut, ) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashAmt));

        // After calling CashOut, under the correct contract the stored balance for depositor remains >= 0
        // and specifically cannot increase due to CashOut; we assert that balances(depositor) <= before (i.e., CashOut cannot increase recorded balance)
        // This is a single general assertion reading c's public getter.
        uint256 after = c.balances(depositor);
        assertTrue(after <= before);
    }
}
